#include <iostream>
#include <string>

class Velocity {
    int m_speed;
    std::string m_dir;
public:
    Velocity(int speed, std::string dir)
        : m_speed{ speed }, m_dir{ dir }
    {}

    Velocity(int speed)
        : Velocity{ speed, "north" }
    {}

    int speed() const { return m_speed; }
    const std::string& dir() const { return m_dir; }
};

int main() {
    int s1{};
    std::string d1{};
    int s2{};
    std::cin >> s1 >> d1 >> s2;

    Velocity full{ s1, d1 };
    Velocity defaulted{ s2 };

    std::cout << "Speed: " << full.speed() << " Direction: " << full.dir() << "\n";
    std::cout << "Speed: " << defaulted.speed() << " Direction: " << defaulted.dir() << "\n";
}
